    23  static vcardstructuredtype *vcardstructured_alloc(void)
    24  {
    25      struct vcardstructuredtype_impl *st;
    26
    27      st = icalmemory_new_buffer(sizeof(struct vcardstructuredtype_impl));
    28      if (!st) {
    29          icalerror_set_errno(ICAL_NEWFAILED_ERROR);
    30          return NULL;
    31      }
    32      memset(st, 0, sizeof(struct vcardstructuredtype_impl));
    33
    34      return st;
    35  }
